INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142776, 'spa', 'La contraparte pasiva del sentido 3, enfocada en decretos y edictos como sujetos', 'La contraparte pasiva del sentido 3, enfocada en decretos y edictos como sujetos que ''son cambiados'' o ''no pueden ser cambiados.'' Daniel 6:8 y 6:15 invocan la famosa inmutabilidad de las leyes de los medos y persas — el decreto ''no puede ser cambiado.'' Daniel 4:16 aplica la voz pasiva al corazón de Nabucodonosor, transformado de humano a animal. El español ''puede ser cambiada'' y ''sea cambiado'' reflejan la estructura pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142778, 'spa', 'El sentido causativo activo-transitivo aparece cuando un agente poderoso altera ', 'El sentido causativo activo-transitivo aparece cuando un agente poderoso altera algo deliberadamente: Dios cambia los tiempos y las estaciones (Dn 2:21), el perseguidor de los santos pretende cambiar los tiempos y la ley (Dn 7:25), y tres hombres transgredieron la palabra del rey al negarse a postrarse (Dn 3:28). Esdras 6:11-12 extiende esto a los edictos reales — quien altere el decreto enfrentará destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142790, 'spa', 'Odio como emoción o disposición', 'Odio como emoción o disposición. Actitud hostil sostenida que en la literatura sapiencial se opone al amor (אַהֲבָה) y produce contienda y encubrimiento (Prov 10:12, 18; 15:17; 26:26). En la narrativa puede denotar intensa repulsión sexual (2 Sam 13:15). Los Salmos hablan de ''palabras de odio'' que rodean al inocente (Sal 109:3, 5), y Deuteronomio registra la queja de Israel atribuyendo odio a Dios (Deut 1:27; 9:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142801, 'spa', 'El sentido activo Piel de alterar o modificar deliberadamente algo —el comportam', 'El sentido activo Piel de alterar o modificar deliberadamente algo —el comportamiento de una persona, un nombre o un conjunto de circunstancias. David ''cambió su conducta'' ante Aquis (1 S 21:14), y Dios declara que no alterará la fidelidad que ha salido de sus labios (Sal 89:34). Se trata del acto transitivo e intencional de transformar algo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142802, 'spa', 'El sentido reflexivo Hitpael de disfrazarse —literalmente ''cambiarse a sí mismo''', 'El sentido reflexivo Hitpael de disfrazarse —literalmente ''cambiarse a sí mismo'' para volverse irreconocible. Atestiguado una vez en 1 Reyes 14:2, cuando se le dice a la esposa de Ahías que altere su apariencia antes de visitar al profeta. La morfología reflexiva capta perfectamente la naturaleza autodirigida de la transformación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142804, 'spa', 'El sentido intransitivo Qal de ser diferente, divergir o experimentar cambio', 'El sentido intransitivo Qal de ser diferente, divergir o experimentar cambio. En Ester 1:7, los vasos de oro son descritos como ''diferentes'' unos de otros, y Ester 3:8 señala que las leyes judías son ''diferentes'' de las de otros pueblos. Malaquías 3:6 emplea este sentido teológicamente: ''Yo, el Señor, no cambio''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142809, 'spa', 'Un uso Piel con connotación marcadamente negativa', 'Un uso Piel con connotación marcadamente negativa: pervertir o distorsionar. En Proverbios 31:5, la bebida fuerte amenaza con hacer que un rey ''cambie'' (es decir, pervierta) los derechos de los afligidos. No se trata de una alteración neutral sino de una tergiversación injusta de lo que debería permanecer recto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142811, 'spa', 'Un sentido Piel de reubicación física —trasladar o mover a alguien de un lugar a', 'Un sentido Piel de reubicación física —trasladar o mover a alguien de un lugar a otro. En Ester 2:9, el rey ''trasladó'' a Ester y a sus doncellas a los mejores aposentos del harén. El sentido espacial y logístico lo distingue claramente de los sentidos abstractos de alteración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142814, 'spa', 'Ser repetido', 'Forma pasiva Nifal que denota algo que se repite o se duplica. En Gn 41:32, José explica que el sueño de Faraón fue ''repetido'' (duplicado) porque el asunto está firmemente establecido por Dios. La construcción pasiva desplaza el foco del agente al evento mismo: la repetición del sueño señala certeza divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142815, 'spa', 'Repetir, hacer de nuevo', 'Hacer por segunda vez o repetir una acción. Las formas Qal expresan consistentemente la repetición activa: golpear de nuevo en batalla (1 Sam 26:8; 2 Sam 20:10), verter agua repetidamente sobre el altar (1 Re 18:34), volver a la transgresión como el perro que vuelve a su vómito (Prov 26:11), o insistir en un asunto (Prov 17:9). Las traducciones al español ''repetid'' y ''repetiré'' confirman este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142824, 'spa', 'Año(s)', 'Sustantivo femenino arameo que denota un año, usado en singular constructo (שְׁנַת) para fechar eventos por años de reinado (Esd 5:13; 4:24; 6:15) y en plural (שְׁנִין) para contar duraciones (Esd 5:11; Dn 6:1). Cognado del hebreo שָׁנָה, funcionalmente idéntico como unidad de tiempo calendárica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142829, 'spa', 'Año, unidad de tiempo', 'La unidad estándar de medida temporal anual, usada para edades genealógicas (Gn 5:3-5), datación de reinados, ciclos sabáticos y de jubileo (Lv 25:4, 10) y períodos proféticos. Las formas de singular, dual y plural, junto con toda combinación preposicional y constructa, apuntan a un concepto temporal único e indiferenciado. Las glosas interlingüísticas convergen con claridad: español años, francés ans, alemán Jahre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142857, 'spa', 'El estado físico de sueño o somnolencia, que abarca tanto el descanso nocturno n', 'El estado físico de sueño o somnolencia, que abarca tanto el descanso nocturno natural como, por extensión, la pereza o el letargo. Frecuentemente emparejado con תְּנוּמָה (''modorra'') en Proverbios (6:4, 10; 24:33). La expresión idiomática ''el sueño huyó de mis ojos'' (Gn 31:40; Est 6:1) lo presenta como algo que puede ser interrumpido por intervención divina. Aparece en momentos narrativos vívidos: Jacob despertando de su sueño en Betel (Gn 28:16), Sansón despertando sin saber que su fuerza lo había abandonado (Jue 16:14, 20), y la sabiduría advirtiendo al perezoso contra el sueño excesivo (Pr 6:4, 9-10; 20:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142872, 'spa', 'El color escarlata o carmesí, derivado del tinte del insecto quermes, usado de f', 'El color escarlata o carmesí, derivado del tinte del insecto quermes, usado de forma atributiva para telas, vestiduras y materiales. Este sentido domina los textos de construcción del Tabernáculo (Éx 25:4; 26:1, 31, 36) y las vestiduras sacerdotales (Éx 28:5-8), donde la escarlata aparece en una tríada fija con azul y púrpura. También se extiende a los rituales de purificación (Lv 14:4, 6, 49; Nm 19:6) y a la imagen poética de Isaías sobre el pecado permanente (Is 1:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142874, 'spa', 'Hilo o cordón de escarlata como objeto físico concreto que sirve de marca o seña', 'Hilo o cordón de escarlata como objeto físico concreto que sirve de marca o señal. Mientras que el sentido cromático es atributivo, este uso trata el material escarlata como un elemento identificable y tangible. La partera ata hilo escarlata en la mano de Zéraj para marcar al primogénito (Gn 38:28, 30), y el cordón escarlata de Rajab en su ventana se convierte en señal de pacto para la liberación (Jos 2:18, 21). El Cantar de los Cantares compara los labios de la amada con un hilo de escarlata (Cnt 4:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142884, 'spa', 'ordinal: segundo', 'El número ordinal ''segundo'' en todas sus formas gramaticales: definido e indefinido, masculino y femenino, con preposiciones y conjunciones. Se usa temporal (''el segundo día'', Gn 7:11; ''el segundo año'', Gn 47:18), secuencialmente (''el segundo hijo'', Gn 41:52) y adverbialmente con el sentido de ''por segunda vez'' o ''de nuevo'' (Gn 22:15; Mal 2:13). Las glosas multilingües confirman uniformemente el valor ordinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142891, 'spa', 'borde, labio, orilla', 'Una única aparición en 1 Reyes 7:23 donde la forma parece designar el ''labio'' o ''borde'' del mar de bronce fundido, probablemente un homógrafo o una anomalía de etiquetado que lo sitúa bajo la raíz ordinal en lugar de un sustantivo independiente. Las glosas multilingües — inglés ''its brim'', español ''borde de él'', francés ''son brim'' — apuntan todas a un borde o reborde físico, claramente distinto del uso ordinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142895, 'spa', 'Numeral cardinal dos', 'El numeral cardinal básico ''dos,'' usado para contar pares de personas, objetos, unidades de tiempo o medidas: 666 apariciones, con amplia diferencia el sentido dominante. Lamec toma ''dos mujeres'' (Gn 4:19); Matusalén vive ''dos y ochenta y setecientos años'' (Gn 5:26); Moisés recibe ''dos tablas de piedra'' (Éx 31:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142899, 'spa', 'Ambos (pronominal)', 'Uso pronominal ''ambos'': 73 apariciones donde las formas con sufijo (שְׁנֵיהֶם, שְׁנֵינוּ, שְׁנֵיכֶם, etc.) significan ''ambos/los dos,'' enfatizando la totalidad de un par más que el mero conteo. Adán y Eva ''estaban ambos desnudos'' (Gn 2:25); Abraham e Isaac ''iban ambos juntos'' hacia Moriah (Gn 22:6, 8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142907, 'spa', 'Doce (numeral compuesto)', 'Componente constructo del numeral compuesto ''doce'' (שְׁנֵים עָשָׂר / שְׁתֵּים עֶשְׂרֵה): 27 apariciones incluyendo el ordinal ''duodécimo'' en fórmulas de datación. Moisés erige doce pilares (Éx 24:4); el pectoral del sumo sacerdote lleva doce piedras para las doce tribus (Éx 28:21); el pan de la proposición consta de doce tortas (Lv 24:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142916, 'spa', 'El doble (multiplicativo)', 'Sentido multiplicativo ''el doble'': 3 apariciones en las leyes de restitución de Éxodo 22, donde el ladrón debe devolver ''el doble'' (שְׁנַיִם) de lo robado (Éx 22:4, 7, 9). El español el doble, el francés double y el alemán doppelt seleccionan vocabulario multiplicativo en lugar de numeral cardinal, confirmando un sentido cuantitativo-proporcional distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142940, 'spa', 'Escarnio proverbial', 'Palabra cortante o burla que convierte a alguien en objeto de escarnio público. Usada en contextos de maldición pactual: Israel será refrán de mofa entre las naciones si desobedece (Dt 28:37, 1 R 9:7, 2 Cr 7:20, Jer 24:9). No es un simple insulto, sino humillación codificada en proverbio: la vergüenza de un pueblo se vuelve ejemplo invocado como muestra de juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142941, 'spa', 'Topónimo amorreo', 'Nombre amorreo del monte Hermón o de sus cumbres septentrionales (Dt 3:9 detalla los diferentes nombres regionales). Sirve como marcador fronterizo al norte (1 Cr 5:23), imagen poética de alturas remotas (Cnt 4:8) y fuente de madera de ciprés para la construcción naval fenicia (Ez 27:5). La conservación de este topónimo amorreo en las Escrituras hebreas refleja la realidad multilingüe del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142942, 'spa', 'Afilar (arma o hoja)', 'Afilar o aguzar una hoja, flecha o arma (Qal). Incluye formas activas (''afilaré mi espada reluciente,'' Dt 32:41) y participios pasivos (''flechas afiladas,'' Is 5:28; Sal 45:5). Con frecuencia es metafórico: lenguas afiladas como espadas para el habla calumniosa (Sal 64:3; 140:3; 120:4). Las traducciones ''afilaron/afilada'' reflejan consistentemente la imagen del filo cortante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142946, 'spa', 'Enseñar diligentemente (Piel)', 'Enseñar con diligencia o grabar el conocimiento mediante la repetición (Piel intensivo). Una sola ocurrencia, pero de importancia teológica fundamental, en el pasaje del Shemá (Dt 6:7): los padres deben ''aguzar'' las palabras de Dios en sus hijos. El español ''las repetirás'' capta el matiz de impresión iterativa: no simplemente enseñar, sino grabar mediante el ensayo persistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142947, 'spa', 'Ser traspasado (Hitpael)', 'Ser punzado o herido interiormente (Hitpael reflexivo/pasivo). En Sal 73:21, el salmista describe su tormento interior: ''se llenó de amargura mi corazón y en mis entrañas sentía punzadas.'' El español ''eran punzados'' transmite la aguda angustia interna, una experiencia reflexiva de la misma agudeza que en otros contextos corta hacia afuera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142950, 'spa', 'Sinar (topónimo)', 'Nombre geográfico de la llanura aluvial del sur de Mesopotamia, identificada con Sumeria y Babilonia. Génesis lo usa para el reino de Nimrod (Gn 10:10) y el sitio de la Torre de Babel (Gn 11:2). Aparece como dominio del rey Amrafel (Gn 14:1, 9). Josué 7:21 menciona un ''manto de Sinar'' entre el botín de Acán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142954, 'spa', 'Saquear, saqueador (Qal)', 'Qal activo: saquear o despojar, incluyendo participios agentivos que significan «saqueadores» o «asaltantes». Jueces 2:14, 16 lo usa para quienes saquearon a Israel; 1 Samuel 14:48 para Saúl rescatando a Israel de su saqueador; 1 Samuel 23:1 para los filisteos saqueando las eras. El paralelo con bozez en Isaías 17:14 confirma el campo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142956, 'spa', 'Ser saqueado (Qal pasivo)', 'Participio pasivo Qal: ser despojado, describiendo el estado de haber sido saqueado. Isaías 42:22 declara al pueblo siervo como «saqueado», marcando la condición de la víctima. Esta única ocurrencia invierte el enfoque habitual en el agente, convirtiendo a Israel en la imagen misma de la devastación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142960, 'spa', 'Saquear a fondo (Piel)', 'Piel intensivo: saquear de manera exhaustiva y completa. Isaías 10:13 pone esto en boca del rey asirio que se jacta de sus conquistas: «Saqueé sus tesoros». El tronco Piel transmite totalidad y fuerza más allá del Qal básico, ajustándose a la retórica de la jactancia imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142964, 'spa', 'Saquear y despojar', 'Saquear, despojar o arrebatar por la fuerza, aplicado tanto al pillaje activo como a la victimización pasiva. El Qal activo describe a enemigos saqueando a Israel (Jue 2:14; Sal 89:41) y a Israel saqueando a los filisteos (1 Sam 17:53). El Nifal pasivo retrata casas siendo saqueadas durante un asedio (Isa 13:16; Zac 14:2). ''Saquearon'' en español y ''pillèrent'' en francés transmiten con precisión la violenta incautación de bienes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142965, 'spa', 'Hender, partir (pezuñas)', 'Partir o tener pezuñas hendidas (Qal). El rasgo diagnóstico en la ley dietética israelita: los animales que ''hienden la pezuña'' son candidatos a la categoría de puro (Lv 11:3, 7, 26; Dt 14:6-7). Las traducciones ''hendidura/hiende'' reflejan la precisión taxonómica. Las cinco apariciones se concentran en la legislación de pureza del Pentateuco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142966, 'spa', 'Contener, refrenar (Piel extendido)', 'Contener o refrenar (Piel extendido/metafórico). En 1 Sam 24:7, David ''separó'' — es decir, contuvo o frenó — a sus hombres para que no mataran a Saúl. La traducción ''contuvo'' confirma la extensión metafórica: la fuerza que desgarra físicamente también puede cortar y refrenar un impulso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142967, 'spa', 'Desgarrar, despedazar (Piel)', 'Desgarrar o despedazar con fuerza violenta (Piel intensivo). Sansón despedazando un león a mano limpia ''como quien despedaza un cabrito'' (Jue 14:6) y el desgarro ritual de un ave por sus alas en el holocausto (Lv 1:17). Las traducciones ''despedazar/desgarrará'' captan la intensidad visceral de este uso en Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142973, 'spa', 'Pezuña hendida', 'La hendidura o división de la pezuña de un animal, empleada específicamente en la ley dietética levítica para distinguir animales puros de impuros. Los animales puros deben tener la pezuña hendida y rumiar (Lv 11:3, Dt 14:6). El cerdo tiene pezuña hendida pero no rumia, por lo cual es impuro (Lv 11:7). Esta característica física se convierte en criterio taxonómico, parte de la ordenación simbólica de la creación por parte de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142975, 'spa', 'El sentido primario', 'El sentido primario: dirigir la mirada con intención evaluativa. Dios ''miró'' a Abel y su ofrenda con favor (Gn 4:4) pero no ''miró'' la de Caín (Gn 4:5). Faraón ordena a los israelitas que no ''presten atención'' a palabras vanas (Éx 5:9). El salmista en 119:117 pide poder ''contemplar'' continuamente los estatutos de Dios. La cualidad intencional y evaluativa de esta mirada es central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142976, 'spa', 'Estar consternado o alarmado (Hitpael)', 'Estar consternado o alarmado (Hitpael): extensión reflexivo-intensiva donde el ''mirar alrededor'' presa del pánico se convierte en terror interior. Isaías 41:10 asegura a Israel: ''no desmayes'', e Isaías 41:23 desafía a los falsos dioses a causar consternación si pueden. El salto semántico va de la mirada física a la perturbación emocional —los ojos moviéndose frenéticamente de miedo se transforman en angustia interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142978, 'spa', 'Apartar la mirada o desviar los ojos', 'Apartar la mirada o desviar los ojos: se usa en súplicas de alivio ante el escrutinio divino. Job ruega a Dios ''aparta tu mirada de mí'' para tener un momento de descanso (Job 7:19; 14:6). Isaías clama ''apartad la mirada de mí'' en un dolor abrumador por la destrucción de Jerusalén (Is 22:4). La construcción hebrea con ''min'' (lejos de) marca esta dirección opuesta al sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142982, 'spa', 'Apartar la mirada en el Hifil causativo', 'Apartar la mirada en el Hifil causativo: hacer que la propia mirada se retire —un desvío activo y deliberado. El Salmo 39:13 suplica a Dios que ''aparte su mirada de mí'' antes de la muerte. La forma Hifil añade intencionalidad más allá del simple Qal: no simplemente dejar de mirar sino redirigir activamente la atención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142986, 'spa', 'Oscurecerse o cerrarse (de los ojos)', 'Oscurecerse o cerrarse (de los ojos): deterioro físico de la vista. Isaías 32:3 promete un día futuro en que ''los ojos de los que ven no se cerrarán'' —usando este verbo para el nublarse o apagarse de la visión. La conexión semántica con la raíz es clara: los ojos que antes ''miraban'' ahora fallan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142989, 'spa', 'Momento o instante', 'Un breve momento u hora, palabra aramea de tiempo que enfatiza la inmediatez y lo repentino en las narraciones de Daniel. La frase idiomática בַּהּ־שַׁעֲתָא (''en ese mismo momento'') aparece en Daniel 3:6, 15 (la orden de postrarse ante la imagen), 4:33 (la transformación de Nabucodonosor) y 5:5 (la escritura en la pared). El español ''hora'' y el inglés ''hour'' traducen el término de forma convencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (142993, 'spa', 'Macho cabrío', 'Macho cabrío. Macho cabrío utilizado en contextos sacrificiales y rituales, el significado principal en 52 apariciones, central en la legislación sacerdotal. Abarca desde Gn 37:31, donde los hermanos de José mojan su túnica en sangre de macho cabrío, hasta Lv 4:23-24 para la ofrenda por el pecado, y Lv 16:5-22 para el Día de la Expiación, donde dos machos cabríos cumplen funciones complementarias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143003, 'spa', 'Criatura peluda, sátiro', 'Criatura peluda, sátiro. Criatura peluda aplicada en sentido figurado. En Daniel 8:21 el término se usa simbólicamente para el rey de Grecia, probablemente como glosa de צָפִיר (''macho cabrío''). ''El peludo'' pone en primer plano el sentido etimológico de vellosidad en vez del animal sacrificial. Este uso tiende un puente entre el animal literal y el simbolismo visionario de la imaginería apocalíptica de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143005, 'spa', 'Demonio cabrío', 'Demonios cabríos o sátiros: seres sobrenaturales con rasgos caprinos, asociados tanto con el culto idolátrico (Lv 17:7, 2 Cr 11:15) como con la presencia inquietante en ruinas desoladas (Is 13:21, 34:14). Representan la adoración prohibida de potencias demoniacas y el caos de la tierra despoblada. Ya se entiendan como espíritus reales o como ídolos en forma de macho cabrío, encarnan todo lo opuesto al culto ordenado del Dios verdadero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143007, 'spa', 'El topónimo propio Seir, que designa la región montañosa al sureste del mar Muer', 'El topónimo propio Seir, que designa la región montañosa al sureste del mar Muerto que se convirtió en la patria territorial de Esaú/Edom. Aparece en tres registros: poesía teofánica donde Dios avanza desde Seir (Jue 5:4; Dt 33:2), narrativa patriarcal donde Esaú se establece en la tierra (Gn 32:3; 33:14, 16; 36:8-9), y oráculos proféticos de juicio contra Edom (Is 21:11; Ez 35:2-15). Los horeos fueron sus habitantes anteriores a los edomitas (Gn 14:6; Dt 2:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143014, 'spa', 'Ancestro horeo', 'Nombre personal de un ancestro horeo cuyos descendientes habitaban la tierra antes de la conquista edomita. Génesis 36:20-21 lista ''los hijos de Seir el horeo, habitantes de la tierra'', luego nombra los siete hijos de Seir que se convirtieron en jefes tribales. 1 Crónicas 1:38 repite esta genealogía. El Seir personal da su nombre a la cordillera y territorio que después se convirtió en Edom, creando el típico patrón bíblico de ancestro epónimo dando nombre a territorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143017, 'spa', 'Hueco de mano/puñado', 'Ya sea el hueco/copa de la mano misma o la cantidad que contiene. 1 Reyes 20:10 usa el plural: Ben-hadad se jacta de que no habrá suficiente polvo en Samaria para dar ''puñados'' a todos sus hombres (un ejército imposiblemente grande). Isaías 40:12 pregunta retóricamente quién ha medido las aguas ''en el hueco de su mano''—solo Dios puede ahuacar los mares en su palma. Ezequiel 13:19 condena profetisas que trabajan por ''puñados de cebada''—compensación insignificante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143018, 'spa', 'Nombre de ciudad cananea-amorrea', 'Nombre de lugar de una ciudad cananea-amorrea que pasó bajo control israelita. Josué 19:42 la asigna al territorio tribal de Dan. Jueces 1:35 nota que los amorreos mantuvieron control allí a pesar de las reclamaciones danitas, hasta que la presión josefita los forzó a trabajos forzados. 1 Reyes 4:9 la muestra integrada en el sistema administrativo de Salomón. Las glosas multilingües simplemente transliteran el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143021, 'spa', 'Apoyarse físicamente, recostar el peso contra algo o reclinarse sobre un soporte', 'Apoyarse físicamente, recostar el peso contra algo o reclinarse sobre un soporte. Abraham invita a sus visitantes a reclinarse bajo el árbol (Gn 18:4), un acantilado geográfico se inclina hacia la frontera de Moab (Nm 21:15), Sansón empuja contra los pilares (Jue 16:26), y el amo de Naamán se apoya en su brazo en el templo (2 R 5:18). Job 8:15 lo usa figuradamente de una telaraña que no puede sostener peso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143023, 'spa', 'Confiar en, depender de o depositar la confianza en — la extensión figurada del ', 'Confiar en, depender de o depositar la confianza en — la extensión figurada del acto de apoyarse. Se usa predominantemente en Crónicas y los profetas para expresar confianza en Dios (2 Cr 13:18; 14:11; Is 10:20; Mi 3:11) o la confianza mal depositada en aliados humanos (2 Cr 16:7-8; Ez 29:7). La construcción típica es נִשְׁעָן עַל seguida del objeto de confianza. El español ''apoyarse'' preserva la transición del sentido físico al relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143040, 'spa', 'Ceguera metafórica espiritual', 'Ceguera metafórica o hacer que los ojos sean incapaces de ver la verdad. Isaías 29:9 lo usa dos veces en el mandato irónico de Isaías a su audiencia: persiste en tu ceguera, tambalea en confusión. Isaías 6:10 instruye al profeta a ''embarrar'' los ojos del pueblo como parte del juicio endurecedor—hacerlos incapaces de ver y comprender. La referencia duplicada en 29:9 (imperativo en Qal e Hitpalpel) intensifica el tono.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143041, 'spa', 'Deleitarse, gozar', 'Experimentar deleite exquisito o placer profundo en algo, un gozo prolongado y contemplativo. Se usa predominantemente para el deleite en la Torá y las consolaciones de Dios. El salmista declara ''me deleito en tus estatutos'' (Sal 119:16, 47, 70) y las consolaciones divinas ''deleitan mi alma'' (Sal 94:19). Isaías 66:12 extiende este sentido al ser acariciado sobre las rodillas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143045, 'spa', 'Jugar, retozar', 'Jugar o retozar, describiendo actividad física inocente y gozosa en contexto de confianza. En Isaías 11:8, la visión mesiánica presenta a un niño que juega (וְשִׁעֲשַׁע) junto a la cueva de la cobra, imagen donde el peligro mortal ha sido abolido y reina deleite despreocupado. El español ''y jugará'' marca el giro del vocabulario contemplativo hacia la acción física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143048, 'spa', 'Estremecerse ante catástrofe', 'Estremecerse o erizarse de horror al presenciar catástrofe. Jeremías 2:12 ordena a los cielos ''estremecerse'' ante el abandono de Dios por Israel—horror cósmico ante violación del pacto. Ezequiel 27:35 describe a reyes de las costas que ''se estremecieron con estremecimiento'' (acusativo cognado) cuando cayó Tiro—sus rostros temblando ante la noticia. Ezequiel 32:10 advierte que las naciones ''se estremecerán'' cuando Dios blande la espada contra Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143049, 'spa', 'Arrebatar como tempestad', 'Arrastrar o arremolinar con fuerza tempestuosa y violenta, como un viento huracanado. Dios barre a los malvados de repente (Sal 58:9); en torno a Dios hay tempestad (Sal 50:3); el viento del este arrebata al impío de su lugar (Job 27:21); un rey arremete como torbellino contra su enemigo (Dn 11:40). El verbo capta la violencia del vendaval: no una erosión gradual, sino una remoción súbita y arrolladora, usada metafóricamente para el juicio divino y la fuerza militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143052, 'spa', 'Cabello de la cabeza', 'Cabello de la cabeza en contextos arameos. Daniel 3:27 enfatiza la completitud del milagro del horno: ni siquiera ''el cabello de sus cabezas'' fue chamuscado. Daniel 4:30 describe la transformación bestial de Nabucodonosor donde ''su cabello creció como plumas de águilas''—largo y descuidado durante su exilio en el desierto. Daniel 7:9 retrata al Anciano de Días con cabello ''como lana pura''—blanco y glorioso, indicando antigüedad y majestad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143053, 'spa', 'Horror estremecedor físico', 'La emoción y estado físico de estremecimiento horrorizado. Job 18:20 dice que los que vienen después ''se apoderaron del estremecimiento'' al contemplar la destrucción del impío. Ezequiel 27:35 y 32:10 lo usan como acusativo cognado con el verbo: reyes y naciones ''se estremecieron con estremecimiento'' ante la caída de Tiro y el juicio de Egipto. El término enfatiza la dimensión involuntaria y física del horror—no solo consternación mental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143055, 'spa', 'puerta, entrada, portón', 'Puerta, entrada o portón físico (337x): la estructura arquitectónica concreta en una muralla urbana, templo, palacio o campamento. Abarca puertas que se abren y se cierran (Jos 2:5-7, Is 45:1), las puertas de la ciudad de Jerusalén (Neh 7:3), las puertas del templo (2 Cr 23:15, 20) y las puertas en la visión profética (Ezequiel 40-48). Las traducciones emplean uniformemente su vocablo para puerta: español puerta, francés porte, alemán Tor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143060, 'spa', 'puertas como territorio', 'Las puertas como metonimia de territorio, comunidad o jurisdicción cívica (38x). Concentrado en la ley deuteronómica, ''dentro de tus puertas'' (בִּשְׁעָרֶיךָ) significa ''dentro de tus poblaciones'', designando las ciudades y el territorio de Israel y no puertas literales. El mandamiento del sábado se extiende al ''extranjero que está dentro de tus puertas'' (Éx 20:10, Dt 5:14), y las instrucciones de Deuteronomio sobre culto y diezmos emplean esta misma fórmula territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143122, 'spa', 'Cabello o pelo humano o animal como sustancia física, examinado en la ley de pur', 'Cabello o pelo humano o animal como sustancia física, examinado en la ley de pureza, consagrado en el ritual nazareo e invocado en descripciones físicas y poesía. El sacerdote levítico inspecciona el color y la condición del cabello para diagnosticar impureza cutánea (Lv 13:3-4, 10, 20-26, 30-32; 14:8-9). El cabello sin cortar del nazareo encarna su consagración a Dios (Nm 6:5, 18). Rasgos personales definitorios se expresan en términos de cabello: Esaú nace ''como un manto de pelo'' (Gn 25:25), Elías es identificado como ''hombre velludo'' (2 R 1:8), y Cantares lo usa poéticamente: ''tu cabello es como un rebaño de cabras'' (Cnt 4:1; 6:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143136, 'spa', 'El cereal cebada (Hordeum vulgare), cultivado ampliamente en el antiguo Israel y', 'El cereal cebada (Hordeum vulgare), cultivado ampliamente en el antiguo Israel y todo el Cercano Oriente. Aparece en contextos agrícolas como cultivo que madura antes que el trigo (Éx 9:31), entre las siete especies de la tierra prometida (Dt 8:8), como grano cosechado que marca el calendario estacional (Rt 1:22; 2:23), en transacciones económicas (Os 3:2; 2 R 7:1) y en ofrendas rituales de grano (Nm 5:15). La cebada era alimento básico tanto para humanos como para el ganado en toda la antigüedad bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143144, 'spa', 'Cabello, un cabello', 'Un solo cabello o hebra de pelo, usado tanto como unidad individual (en expresiones proverbiales sobre precisión y protección divina) como colectivamente para el vello corporal. La frase constructa missaarath rosho (''un cabello de su cabeza'') aparece en garantías solemnes de que ni un solo cabello caerá (1 Sam 14:45; 2 Sam 14:11; 1 Re 1:52), mientras que Jueces 20:16 lo emplea como medida de la puntería de los honderos benjaminitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143151, 'spa', 'acto moralmente horroroso', 'Un acto o cosa tan moralmente escandaloso que horroriza. Jeremías 18:13 identifica la apostasía de Israel como ''una cosa horrible'' sin precedentes entre las naciones. Oseas 6:10 (con variación Ketiv-Qere) describe a Dios viendo ''una cosa horrible'' en la casa de Israel—su adulterio espiritual. La palabra aparece en acusaciones proféticas de violación del pacto, enfatizando no solo la maldad sino su carácter escandaloso y abominable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143154, 'spa', 'nombre de lugar', 'Nombre de lugar que significa ''puertas dobles'' para dos pueblos del sur. Josué 15:36 lo enumera entre los asentamientos de la Sefela de Judá. 1 Samuel 17:52 identifica el camino por el que huyeron los filisteos después de la muerte de Goliat como ''el camino a Saaraim'' (literalmente ''a las puertas''). 1 Crónicas 4:31 lo ubica en territorio simeonita en el Néguev. Las glosas multilingües simplemente transliteran (''Saaraim''), apropiado para nombres propios sin significado transferible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143156, 'spa', 'Deleite, placer exquisito', 'Deleite profundo e intensivo o placer exquisito, siempre en plural de intensidad (שַׁעֲשֻׁעִים). La palabra expresa más que un disfrute ordinario: transmite una especie de gozo arrebatado. En el Salmo 119 (vv. 24, 77, 92, 143, 174), el salmista declara que los testimonios y la Torá de Dios son sus ''delicias'', el gozo sustentador que lo preserva en medio del sufrimiento. En Proverbios 8:30-31, la Sabiduría misma era el deleite cotidiano de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143162, 'spa', 'ribera, orilla (de agua)', 'La ribera u orilla de una masa de agua — 22 apariciones en la geografía narrativa y las promesas divinas. La descendencia de Abraham será multiplicada ''como la arena a la orilla del mar'' (Gn 22:17); las vacas del faraón suben del Nilo ''a la ribera'' (Gn 41:3); Moisés se encuentra con el faraón ''a la orilla del río'' (Éx 7:15). La lógica metafórica es clara: la ribera es el ''labio'' donde el agua se encuentra con la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143163, 'spa', 'labio, labios (cuerpo)', 'El labio o los labios como órgano del habla — la acepción dominante con 123 apariciones en todos los géneros principales. Los labios hablan (Sal 34:13), mienten (Sal 12:2-3), adulan (Pr 7:21), guardan sabiduría (Pr 5:2), tiemblan en oración (1 S 1:13) y son tocados por una brasa en la vocación de Isaías (Is 6:5-7). Moisés protesta ser ''incircunciso de labios'' (Éx 6:12, 30), expresiva metáfora de la dificultad para hablar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143168, 'spa', 'borde, orilla (de objeto)', 'El borde, reborde u orilla de un objeto manufacturado — 23 apariciones concentradas en las narrativas de construcción del tabernáculo (Éx 26-28) y la descripción de los utensilios del templo de Salomón (1 R 7:23-26). Las cortinas del tabernáculo tienen una שָׂפָה (Éx 26:4, 10), el pectoral tiene una שָׂפָה (Éx 28:26) y el gran mar de bronce tiene una שָׂפָה semejante a flor de lirio (1 R 7:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143172, 'spa', 'lengua, idioma (Gn 11)', 'Lengua, idioma o sistema de habla — 8 apariciones, la más célebre en el relato de Babel donde ''toda la tierra tenía una sola שָׂפָה y unas mismas palabras'' (Gn 11:1, 6-7, 9). También en Is 28:11 (''con labio tartamudo y en otra lengua'') e Is 33:19 (''pueblo de habla oscura''). La cadena metonímica es nítida: labio → habla → sistema completo de habla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143214, 'spa', 'elocuencia, don de palabra', 'El habla o la elocuencia como facultad — la única aparición en Job 12:20, donde Dios ''quita el habla a los de confianza'' (שָׂפָה נֶאֱמָנִים). Aquí שָׂפָה no significa ''labio'' (la parte del cuerpo) ni ''idioma'' (el sistema), sino la facultad o el poder del habla persuasiva. El español el habla de y el alemán welcher Mund eligen ''habla/boca'' en lugar de ''labio'' o ''idioma'', indicando que los traductores perciben una acepción distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143237, 'spa', 'Sierva, esclava', 'Sierva, esclava. Criada o esclava perteneciente a un hogar, usada tanto para esclavas reales como Agar (Gn 16:1), Bilhá y Zilpá (Gn 29:24, 29), como para la autodesignación humilde convencional de mujeres que se dirigen a superiores: Ana habla así ante Elí (1 S 1:16) y Abigail ante David (1 S 25:24-28). El español ''sierva'' y el alemán ''Magd'' captan ambas dimensiones de forma consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143267, 'spa', 'juzgar, administrar justicia', 'La acción verbal Qal fundamental: juzgar, dictar sentencias, administrar justicia. Noventa y ocho apariciones, desde Samuel juzgando a Israel en Betel, Gilgal y Mizpa (1 S 7:16) hasta la oración de Salomón pidiendo sabiduría judicial (1 R 3:9). El árabe حَكَمَ, el español juzgar, el francés juger y el coreano 심판하다 convergen en la adjudicación forense.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143268, 'spa', 'juez (persona, cargo)', 'El participio activo Qal lexicalizado como sustantivo ''juez'' (שׁוֹפֵט/שׁוֹפְטִים). Sesenta y una apariciones que abarcan el nombramiento judicial (Dt 16:18), el título divino ''Juez de toda la tierra'' (Gn 18:25) y los magistrados del periodo homónimo. El árabe القاضي, el español el juez y el alemán der Richter confirman su estatus plenamente nominalizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143271, 'spa', 'gobernar, regir', 'Qal extendido de lo judicial a la gobernanza política: gobernar o liderar un pueblo según el modelo premonárquico. Once apariciones: ''Danos un rey que nos juzgue'', es decir, ''que nos gobierne'' (1 S 8:5-6); Moisés sentado todo el día ''juzgando'' como autoridad ejecutiva (Éx 18:13). El árabe قَضَى con connotación de gobierno y el libro de los Jueces confirman a שָׁפַט como término premonárquico de liderazgo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143273, 'spa', 'entrar en juicio, litigar', 'Nifal y formas afines de acción judicial recíproca: entrar en juicio, contender en un pleito, litigar. Trece apariciones, incluyendo el ''entraré en juicio con vosotros'' de Dios (Ez 20:35-36), la futilidad de contender con Dios (Job 9:15) y el tribunal del necio (Pr 29:9). El árabe حَاكَمَ (Forma III, ''litigar'') marca el paso de la autoridad al enfrentamiento adversarial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143275, 'spa', 'vindicar, hacer justicia', 'Formas Qal con fuerza benefactiva o vindicatoria: juzgar a favor de, defender al oprimido. Dieciséis apariciones, incluyendo la súplica de David ''Júzgame, oh Señor'' (Sal 7:9), ''Vindícame, oh Dios'' (Sal 26:1) y el llamado de Isaías a ''hacer justicia al huérfano'' (Is 1:17). El árabe اُحْكُمْ لِي (''juzga a mi favor'') y el español júzgame confirman la orientación favorable al suplicante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143320, 'spa', 'ser juzgado (pasivo)', 'El Nifal pasivo: ser juzgado, comparecer en juicio, someterse a sentencia. Cinco apariciones, incluyendo ''sean juzgadas las naciones delante de ti'' (Sal 9:20), la garantía para el justo (Sal 37:33) y el devastador ''cuando sea juzgado, salga culpable'' (Sal 109:7). El árabe يُدَان y el coreano 심판받다 confirman la voz pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143390, 'spa', 'Juicios, actos judiciales', 'Juicios, actos judiciales. Actos de juicio divino o castigo judicial, siempre en plural שְׁפָטִים, que denotan las intervenciones punitivas de Dios contra Egipto (Éx 6:6; 7:4; 12:12; Nm 33:4), Jerusalén y naciones extranjeras (Ez 5:10, 15; 11:9; 25:11; 28:22, 26; 30:14, 19). A diferencia del más general מִשְׁפָּט (''ordenanza, ley casuística''), este sustantivo enfatiza la dimensión ejecutoria y retributiva de la justicia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143395, 'spa', 'Safat (nombre propio)', 'El nombre propio Safat (שָׁפָט), nombre teofórico que significa ''él ha juzgado'', reflejando la confianza en que Dios ejerce juicio justo. Es más conocido como patronímico del profeta Eliseo — ''Eliseo hijo de Safat'' aparece como fórmula fija en Reyes (1 Re 19:16, 19; 2 Re 3:11; 6:31). También lo llevan un representante simeonita en la exploración del desierto (Nm 13:5) y un descendiente davídico (1 Cr 3:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143398, 'spa', 'Sefatías (nombre de persona) — El nombre propio Sefatías (también Sefatíahu), qu', 'Sefatías (nombre de persona) — El nombre propio Sefatías (también Sefatíahu), que significa ''YHWH ha juzgado'', identifica a múltiples individuos: el quinto hijo de David (2 Sam 3:4), un benjaminita en Jerusalén (1 Cr 9:8), un guerrero que se unió a David en Siclag (1 Cr 12:5), un jefe tribal simeonita (1 Cr 27:16), un hijo de Josafat (2 Cr 21:2), jefes de familias que regresaron del exilio (Esd 2:4; Neh 7:9), y uno de los oficiales que buscaron la muerte de Jeremías (Jer 38:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143403, 'spa', 'Altura pelada, colina árida', 'Lugar elevado, desnudo o desprovisto de árboles; una cima expuesta sin vegetación, empleada para puntos de observación panorámica (Nm 23:3, donde Balaam sube a una altura pelada para recibir un oráculo) y prominentemente en la poesía profética para paisajes desolados asociados al juicio y la idolatría (Jer 3:2, 21; 4:11; 7:29; 12:12; 14:6). Isaías invierte la imagen, prometiendo que Dios abrirá ríos sobre las alturas desnudas (Is 41:18; 49:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143408, 'spa', 'nombre personal', 'Nombre personal en genealogía benjaminita y servicio levítico. 1 Crónicas 7:12 y 7:15 insertan a Sufim en complicadas genealogías tribales (con dificultades textuales que los eruditos debaten). 1 Crónicas 26:16 identifica a Sufim y Hosa como porteros asignados a los recintos occidentales del templo durante la organización del servicio levítico por David. El nombre funciona tanto ancestralmente (marcando una línea familiar) como individualmente (un guardia específico).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143412, 'spa', 'derramar (líquido/libación)', 'Derramar un líquido o una libación (Qal activo, 59x): el sentido físico básico de vaciar un recipiente — agua, aceite, sangre u ofrenda de libación — generalmente en contextos rituales o cotidianos. El español derramar, el francés répandre y el alemán ausgießen convergen en este significado central. Domina el sistema sacrificial levítico: la sangre derramada al pie del altar (Lv 4:7, 12, 18, 25, 30, 34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143416, 'spa', 'derramar sangre (matar)', 'Derramar sangre (Qal, 34x): colocación especializada con דָּם (''sangre'') que forma el modismo bíblico primario para el asesinato y la culpa de sangre. El cognado árabe سَفَكَ preserva esta misma especialización, confirmando la antigüedad de la colocación. El alemán Blut vergießen y el español derramar sangre tratan igualmente ''derramar sangre'' como expresión fija. Fundacional en Gn 9:6 y en todo el Deuteronomio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143422, 'spa', 'ser derramado (Qal pasivo)', 'Ser derramado (Qal pasivo, 8x): formas pasivas del Qal donde el sujeto sufre el derramamiento — sangre que fue vertida, líquido que fue derramado. El español derramada (femenino pasivo) y el francés a été répandu confirman la lectura pasiva. Se distingue del Nifal (acepción 4) por su forma morfológica: construcciones participiales y de perfecto que funcionan como verdaderos pasivos Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143425, 'spa', 'ser derramado (Nifal pasivo)', 'Ser derramado (Nifal, 8x): el tronco pasivo gramaticalmente marcado, que expresa el estado de haber sido vertido o derramado. El alemán ausgegossen (participio pasado) y el español fue derramada marcan la orientación pasiva. Aparece en la fórmula talional de Gn 9:6 (la sangre del asesino ''será derramada''), en la ley deuteronómica del altar donde la sangre ''será derramada'' sobre la tierra (Dt 12:27) y en oráculos proféticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143436, 'spa', 'derramarse (Hitpael reflexivo)', 'Derramarse (Hitpael reflexivo, 3x): el tronco reflexivo que describe algo — un alma, fuerza vital o sustancia — que fluye de sí mismo. En Job 30:16 el alma de Job ''se derrama dentro de mí'' — disolución interior. En Lamentaciones 2:12 la vida de los niños ''se derrama'' en el regazo de sus madres. El español derramarse y el francés se répandre confirman la dimensión reflexiva de esta autodisolución desoladora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143444, 'spa', 'derramar (ira/espíritu)', 'Derramar ira, furor o espíritu (Qal metafórico, 5x): extensión abstracta donde el ''líquido'' derramado es la cólera, la indignación o el Espíritu de Dios. Los oráculos proféticos de juicio dominan: Dios ''derramará'' su furor sobre Jerusalén (Ez 7:8; 9:8; 14:19; 20:8, 13, 21), y Joel promete que Dios ''derramará'' su Espíritu sobre toda carne. La imaginería de vertido se mantiene aplicada a realidades no materiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143490, 'spa', 'El sentido estativo Qal', 'El sentido estativo Qal: estar en un estado bajo, ser abatido o ser humillado, describiendo la condición resultante del abatimiento más que el acto en sí. Concentrado en los oráculos de Isaías contra el orgullo (Is 2:9, 11, 12, 17; 5:15), donde todo lo exaltado será rebajado. El español ''será humillada'' subraya la naturaleza involuntaria y decretada de esta humillación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143493, 'spa', 'El sentido causativo Hifil', 'El sentido causativo Hifil: abatir, humillar, rebajar o derribar activamente a otra persona, nación o entidad. Aparece 16 veces, frecuentemente con Dios como sujeto ejerciendo autoridad soberana sobre los soberbios (1 S 2:7; 2 S 22:28; Job 40:11). El español ''humillar'' transmite esta fuerza activa dirigida hacia abajo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143501, 'spa', 'El Hifil usado intransitiva o reflexivamente', 'El Hifil usado intransitiva o reflexivamente: humillarse a sí mismo, inclinarse o condescender voluntariamente. El Salmo 113:6 celebra a Dios que ''se humilla'' (mashpili) para mirar los cielos y la tierra — un asombroso acto divino de autoabajamiento. Solo 3 ocurrencias, pero teológicamente poderosas, representando un abajamiento deliberado por elección y no por compulsión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143514, 'spa', 'Humillar, abatir', 'Humillar, rebajar o derribar (verbo arameo en Daniel). Se usa para describir a Dios humillando a los soberbios (Dan 4:37), reyes deponiendo a otros (Dan 5:19, 7:24) y la falta de humillar el corazon ante Dios (Dan 5:22). Es un tema central en la teologia de Daniel sobre la soberania divina: los gobernantes orgullosos que rehúsan humillarse son forzosamente abatidos por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143517, 'spa', 'Bajo en estatus o estima', 'Bajo en estatus o estima. Describe a una persona, reino o entidad que es vil, abatida o mantenida en posición subordinada. Incluye la profecía de Ezequiel de que Egipto será ''el más bajo de los reinos'' (Ez 29:14-15), el reino mantenido ''bajo'' para evitar rebelión (Ez 17:14), y la humillación de David ante sus propios ojos (2 Sam 6:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143518, 'spa', 'Bajo en posición física', 'Bajo en posición física. Espacialmente cercano al suelo, hundido respecto a una superficie circundante o disminuido en altura. Incluye el diagnóstico levítico de enfermedades cutáneas donde una lesión aparece ''más baja que la piel'' (Lv 13:20, 21, 26; 14:37), la vid rastrera de Ezequiel 17:6 y el sonido decreciente del molino en la vejez (Ecl 12:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143521, 'spa', 'Humilde de espíritu', 'Humilde de espíritu. Cualidad moral y espiritual positiva que describe a quien no se enaltece sino que camina en dependencia de Dios. Culmina en una de las declaraciones más amadas de las Escrituras: ''Habito en la altura y la santidad, y con el de espíritu contrito y humilde'' (Is 57:15). Proverbios elogia al שָׁפָל רוּחַ (''humilde de espíritu'') como mejor que el altivo (Prov 16:19; 29:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143533, 'spa', 'Tierra baja / región de la Sefela', 'Tierra baja / región de la Sefela. La región de colinas al oeste de la cordillera central de Judá, distinguida consistentemente en las listas geográficas de la montaña, el Néguev y la Arabá (Dt 1:7; Jos 9:1; 10:40). Era conocida por sus arboledas de sicómoros (1 R 10:27) y servía como zona estratégica de amortiguación entre Judá y las ciudades filisteas de la costa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143547, 'spa', 'Bigote o labio superior', 'El bigote o labio superior, la franja de vello facial entre la nariz y la boca. Las cinco apariciones designan esta parte del cuerpo, pero su significado cultural varía: recortarlo señala el fin del duelo (2 Sam 19:24), mientras que cubrirlo indica luto, vergüenza profética (Miq 3:7) o impureza ritual (Lev 13:45). Las traducciones en diversas lenguas confirman uniformemente el referente del bigote.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143552, 'spa', 'Daman o hyrax', 'El daman o hyrax (hyrax syriacus), pequeño mamifero que habita entre las rocas. Clasificado como inmundo en la ley alimentaria (Lv 11:5, Dt 14:7) por aparentar rumiar sin tener pezuñas hendidas. Celebrado en la literatura sapiencial como criatura debil que sabiamente hace su hogar en las grietas de las peñas (Pr 30:26), y el Salmo 104:18 señala las rocas como su refugio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143553, 'spa', 'El nombre propio de un escriba-secretario real en la corte de Josías que cataliz', 'El nombre propio de un escriba-secretario real en la corte de Josías que catalizó la reforma de Judá al leer el rollo de la Torá descubierto ante el rey (2 R 22:3-14; 2 Cr 34:8-20). También designa al patriarca de una familia cuyos hijos desempeñaron papeles clave en la era de Jeremías: Ahicam protegió al profeta (Jer 26:24), Gedalías sirvió como gobernador tras la caída (2 R 25:22; Jer 39:14; 40:5-11), y Elasá llevó la carta de Jeremías a los exiliados en Babilonia (Jer 29:3). La Septuaginta transliteró el nombre como Saphan o Sapphan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143556, 'spa', 'Abundancia, torrente', 'Una gran cantidad o abundancia desbordante, usada para inundaciones literales y profusión figurada de animales o fuerzas naturales. Job pregunta si ''un torrente de aguas'' lo cubre (22:11) y Dios lo desafía sobre comandar ''abundancia de aguas'' (38:34). Isaías 60:6 contempla ''abundancia de camellos'' en la restauración mesiánica y Ezequiel 26:10 describe la multitud de caballos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143557, 'spa', 'Compañía, tropa', 'Una compañía, tropa o banda de personas, particularmente en contexto militar. Las dos apariciones se hallan en 2 Reyes 9:17, donde el centinela en Jezreel divisa ''una tropa'' acercándose y la identifica como ''la tropa de Jehú''. El español ''tropa'' marca un claro desplazamiento desde la abundancia del sentido 1 hacia un grupo organizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143563, 'spa', 'ser agradable/aceptable', 'Ser agradable o aceptable en contextos reales. Daniel 4:2 y 6:1 reportan que ''pareció bien'' al rey Darío o Nabucodonosor nombrar funcionarios o hacer proclamaciones—la idea agradó al rey. Daniel 4:27 expresa la esperanza de Daniel de que su consejo ''sea aceptable'' a Nabucodonosor respecto a romper con los pecados mediante la justicia. Las glosas multilingües (''pareció bien,'' ''seemed good,'' ''te sea agradable'') capturan esta idea de aprobación subjetiva real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143570, 'spa', 'Poner al fuego', 'Poner una olla al fuego, colocar un recipiente para cocinar. El uso literal y doméstico aparece en la instrucción de Eliseo a su siervo (2 Re 4:38) y en la alegoría de Ezequiel sobre la olla (Ez 24:3). El español ''pon'' y el francés ''mettre'' captan el acto concreto de situar algo en posición. Este es el significado raíz del cual se desarrollan las extensiones metafóricas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143574, 'spa', 'Cilicio de duelo', 'Cilicio de duelo. Tela basta (normalmente de pelo de cabra) vestida sobre la piel como señal de luto, lamentación o penitencia ante Dios. Sentido dominante con 42 de 48 apariciones, presente en la literatura profética y narrativa. Jacob se viste de cilicio por José (Gn 37:34), David lo ordena tras la muerte de Abner (2 S 3:31), y Rizpá lo extiende sobre la roca durante su vigilia (2 S 21:10). El salmista lo evoca como expresión de aflicción profunda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143579, 'spa', 'Costal, saco', 'Costal, saco. Saco o costal de material tosco usado para transportar grano o mercancías. Este sentido concreto y utilitario aparece seis veces, concentrado en el ciclo de José, donde los costales de grano de los hermanos se convierten en instrumento de ironía dramática: la plata oculta en sus שַׂקִּים (Gn 42:25, 27, 35). Posiblemente también en Lv 11:32, donde se menciona un שַׂק entre los recipientes que pueden quedar impuros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143594, 'spa', 'Velar, vigilar', 'Mantener vigilia, estar alerta o custodiar atentamente algo o a alguien. Se usa frecuentemente de la supervisión vigilante de Dios: Jeremías 1:12 declara que Dios «vela» sobre su palabra para cumplirla, y Jeremías 31:28 promete que así como Dios veló para arrancar, velará para edificar. Proverbios 8:34 bendice a quien vela cada día a las puertas de la Sabiduría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143595, 'spa', 'Estar desvelado, insomne', 'Estar despierto, permanecer en vela, no poder dormir, describiendo un estado de vigilia sin implicar necesariamente vigilancia intencional. El Salmo 102:7 pinta una imagen desoladora: «Velo y soy como ave solitaria sobre el tejado». El Salmo 127:1 advierte que si el SEÑOR no guarda la ciudad, en vano vela el centinela.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143598, 'spa', 'Acechar, vigilar para mal', 'Vigilar con intención hostil, acechar o emboscar para hacer daño. Isaías 29:20 denuncia a «los que velan para la iniquidad», e Jeremías 5:6 retrata a un leopardo que «acecha contra sus ciudades» para atrapar a quien se aventure a salir. El matiz depredador y amenazante invierte la vigilancia protectora del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143605, 'spa', 'Forma de almendra', 'Labrado en forma de flores de almendro, un término técnico para las copas decorativas del candelabro de oro. Las seis apariciones se encuentran en las instrucciones sacerdotales del tabernáculo (Éxod 25:33-34; 37:19-20), describiendo cálices modelados como flores de almendro. La derivación de שָׁקַד (almendro) vincula este detalle ornamental con un árbol rico en matices simbólicos de vigilancia y floración temprana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143606, 'spa', 'Almendro o almendra', 'El almendro o sus frutos. Las almendras aparecen como bienes valiosos de comercio (Gn 43:11) y como señal milagrosa en la vara florecida de Aaron (Nm 17:8). El arbol figura en la alegoria de la vejez (Ec 12:5) y en la vision de Jeremias con el juego de palabras sobre «velar» (Jr 1:11). Apreciado por su floracion temprana, el almendro simboliza vigilancia y despertar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143607, 'spa', 'Regar o irrigar la tierra', 'Regar o irrigar la tierra. Regar o irrigar tierras, jardines o plantas, con 9 apariciones donde el objeto es agrícola y no animado. El río sale del Edén ''para regar el jardín'' (Gn 2:10), la niebla sube ''para regar toda la faz de la tierra'' (Gn 2:6), y la tierra de Egipto requiere riego manual a diferencia del suelo de Canaán alimentado por la lluvia (Dt 11:10). El español ''regar'' marca claramente el cambio al dominio agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143608, 'spa', 'Dar de beber a seres vivos', 'Dar de beber a seres vivos. Dar de beber a personas o animales, el sentido principal con 51 apariciones. Rebeca abreva los camellos (Gn 24:14-46), las hijas de Lot dan vino a su padre (Gn 19:32-35), Agar da agua a Ismael (Gn 21:19), y el salmista pide a Dios que ''les dé lágrimas a beber'' (Sal 80:5). El español ''dar de beber'' y el árabe saqaa seleccionan consistentemente vocabulario de bebida interpersonal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143630, 'spa', 'Hundirse (texto problemático)', 'Hundirse (texto problemático). Aparición problemática en Amós 8:8 donde el texto probablemente está corrupto o implica una raíz diferente. La confusión multilingüe es visible: el español traduce ''y se hundirá'', el inglés da la marca [K], y el alemán ofrece la forma hebrea cruda. El contexto describe la tierra subiendo y hundiéndose como el Nilo, lo que sugiere que puede pertenecer a una raíz que significa ''hundirse'' más que a שָׁקָה.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143634, 'spa', 'Estar regado, bien nutrido', 'Estar regado, bien nutrido. Aparición aislada en Job 21:24 donde el verbo parece significar ''estar humedecido'' o ''estar bien regado'', describiendo la médula o el cuerpo del impío como plenamente nutrido. El español ''está regado'' y el inglés ''is moistened'' apuntan a un sentido estativo o pasivo —el cuerpo está en estado de saturación— en lugar del causativo activo que se encuentra en otras partes. Podría representar un raro uso Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143659, 'spa', 'Un ídolo detestable o deidad específica señalada por nombre o epíteto', 'Un ídolo detestable o deidad específica señalada por nombre o epíteto: ''Astarté, el שִׁקּוּץ de los sidonios,'' ''Quemos, el שִׁקּוּץ de Moab'' (1 R 11:5, 7; 2 R 23:13). El שִׁקּוּץ מְשֹׁמֵם de Daniel — la abominación desoladora (Dn 11:31; 12:11) — se volvió teológicamente decisivo, referenciado por Jesús en Mateo 24:15. La forma constructa enfatiza un objeto aborrecible particular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143660, 'spa', 'Cosas detestables o abominaciones idolátricas colectivamente — el plural שִׁקּוּ', 'Cosas detestables o abominaciones idolátricas colectivamente — el plural שִׁקּוּצִים denunciando todo el aparato de la adoración de ídolos de una nación. Ezequiel lo usa repetidamente (5:11; 7:20; 11:18, 21; 20:7-8, 30; 37:23), al igual que Jeremías (4:1; 7:30; 13:27; 16:18) y los historiadores deuteronomistas (Dt 29:17; 2 R 23:24). El español ''abominaciones'' transmite el asco visceral del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143666, 'spa', 'Inmundicia o materia contaminante que enfatiza la polución y el asco más que un ', 'Inmundicia o materia contaminante que enfatiza la polución y el asco más que un contenido específicamente idolátrico. Nahúm 3:6 declara que Dios arrojará ''inmundicias'' (שִׁקּוּץ) sobre Nínive, y Zacarías 9:7 lo aplica a alimentos impuros. Este sentido más amplio connota una repulsividad contaminante que va más allá de la idolatría propiamente dicha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143677, 'spa', 'El sentido intransitivo básico', 'El sentido intransitivo básico: estar en estado de quietud, reposo o sin perturbación. Frecuentemente describe una tierra en paz después de un conflicto militar, como en la fórmula recurrente de Jueces ''y la tierra reposó'' (Jue 3:11; 5:31). También se usa para el descanso personal, como en Job 3:13, 26, donde Job lamenta la quietud que nunca encontró. Transmite una calma asentada y profunda tras la agitación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143680, 'spa', 'El participio Qal funcionando como adjetivo o sustantivo, describiendo a una per', 'El participio Qal funcionando como adjetivo o sustantivo, describiendo a una persona, pueblo o lugar como habitualmente quieto, asentado y sin perturbación. Los espías en Jueces 18:7 encontraron un pueblo ''quieto y confiado'', y Ezequiel 38:11 habla de quienes ''viven tranquilos'' en aldeas sin muros. Se refiere a una condición estable y característica de paz, no meramente a la ausencia momentánea de conflicto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143683, 'spa', 'El infinitivo absoluto Hifil usado como sustantivo abstracto que denota el estad', 'El infinitivo absoluto Hifil usado como sustantivo abstracto que denota el estado o condición de quietud, reposo o tranquilidad en sí misma. Isaías 30:15 declara célebremente ''en quietud y confianza será vuestra fortaleza'', e Isaías 32:17 la vincula con la justicia. Jeremías 49:23 la usa negativamente — el mar que ''no puede estar quieto''. Este uso nominal eleva שָׁקַט de verbo descriptivo a concepto teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143692, 'spa', 'El sentido causativo Hifil', 'El sentido causativo Hifil: hacer que alguien esté quieto, conceder descanso o calmar. Dios es típicamente el agente implícito o explícito. En el Salmo 94:13, Dios ''da reposo'' al afligido de los días de adversidad. Proverbios 15:18 señala que el paciente ''apacigua'' la contienda. Este es reposo otorgado, no meramente experimentado — una dimensión activa y relacional del descanso divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143709, 'spa', 'Pesar plata o dinero en una balanza como forma de pago o transacción comercial, ', 'Pesar plata o dinero en una balanza como forma de pago o transacción comercial, el medio estándar de intercambio antes de la acuñación de monedas. La compra de Macpela por Abraham (Gn 23:16), la adquisición del campo por David y la entrega de los utensilios del templo por Esdras (Esd 8:25-26) reflejan este sentido mercantil concreto. El español pesar y el francés peser confirman la acción física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143711, 'spa', 'Pesar en el sentido de evaluar, examinar o determinar el verdadero valor, frecue', 'Pesar en el sentido de evaluar, examinar o determinar el verdadero valor, frecuentemente con Dios como sujeto que prueba corazones y motivos. Proverbios 16:2 y 21:2 declaran que YHWH pesa los espíritus, mientras que Job 31:6 pide ser pesado en balanza de justicia. Isaías 40:12 extiende la imagen a escalas cósmicas, preguntando quién ha pesado los montes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143728, 'spa', 'Nifal pasivo', 'Nifal pasivo: ser pesado en la balanza, ya sea literalmente referido a la plata cuyo valor no puede medirse como pago por la sabiduría (Job 28:15), o en la célebre escena del juicio donde Belsasar es pesado y hallado falto (Dn 5:27). El cognado arameo teqal en la inscripción de Daniel subraya la antigua conexión entre peso y veredicto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143731, 'spa', 'Siclo (unidad de peso/moneda)', 'Siclo (unidad de peso/moneda). Unidad estándar de peso de aproximadamente 11,4 gramos que servía como principal medida de valor del antiguo Israel para plata, oro y bronce. Funciona tanto como peso colocado en la balanza como denominación monetaria en transacciones comerciales y cultuales. Desde los inventarios del tabernáculo (Éx 38:24-29) hasta la denuncia de Amós contra los comerciantes deshonestos (Am 8:5), el siclo es la medida económica básica de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143742, 'spa', 'Sicómoro (Ficus sycomorus)', 'El sicómoro o higuera-sicómoro (Ficus sycomorus), un gran árbol de tierras bajas común en la Sefela del antiguo Israel, valorado tanto por su madera como por su fruto similar al higo. La riqueza de Salomón hizo que los cedros fueran tan comunes como los sicómoros (1 Re 10:27 = 2 Cr 1:15 = 9:27), y un administrador real supervisaba los plantíos de sicómoros (1 Cr 27:28). Amós se describió a sí mismo como בּוֹלֵס שִׁקְמִים, cultivador o perforador del fruto del sicómoro (Am 7:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143748, 'spa', 'Hacer hundir, asentar', 'Sentido causativo Hiphil: presionar hacia abajo, hacer asentar, provocar hundimiento. Dios declara ''haré asentar sus aguas'' en Ezequiel 32:14, donde hundirse se matiza hacia clarificar: aguas turbias calmándose hasta la transparencia. En Job 41:1 se pregunta si se puede presionar la lengua de Leviatán con un cordel. El español ''asentar'' y ''hundir'' separan lo que el hebreo unifica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143749, 'spa', 'Hundirse, aplacarse', 'El sentido intransitivo Qal/Nifal de hundirse, aplacarse, sumergirse. El fuego ''se apaga'' tras la intercesión de Moisés (Núm 11:2). La tierra sube y baja como el Nilo en Amós 8:8 y 9:5, donde el español ''hundirse'' capta el colapso físico. Jeremías 51:64 lo aplica a la sumersión irreversible de Babilonia, una imagen profética de descenso permanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143755, 'spa', 'Mirar hacia abajo desde una altura en la conjugación Hifil', 'Mirar hacia abajo desde una altura en la conjugación Hifil: una mirada deliberada descendente desde una posición elevada como el cielo, una montaña o una ventana. Con 12 apariciones, este sentido incluye a Dios mirando desde el cielo a los egipcios a través de la columna de fuego (Éx 14:24), Moisés instruyendo a Israel a pedir a Dios que mire desde su santa morada (Dt 26:15) y Abraham contemplando el humo de Sodoma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143756, 'spa', 'Dominar o dar hacia un lugar', 'Dominar o dar hacia un lugar: participio Nifal topográfico que describe un accidente geográfico o posición elevada que mira sobre un área. Con 4 apariciones, este uso especializado funciona como descriptor del paisaje: el campo de Zofim en la cumbre del Pisga, que domina el desierto (Nm 21:20; 23:28), la colina que da hacia Jesimón (1 S 13:18) y la amada que resplandece como el alba (Cnt 6:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143759, 'spa', 'Asomarse o mirar hacia abajo desde una ventana o punto de observación en la conj', 'Asomarse o mirar hacia abajo desde una ventana o punto de observación en la conjugación Nifal: un acto reflexivo de mirar hacia afuera, frecuentemente cargado de tensión emocional. Con 6 apariciones, este sentido se presenta en algunas de las escenas más vívidas de la Escritura: la madre de Sísara mirando por la celosía esperando el regreso de su hijo (Jue 5:28), Mical observando a David danzar ante el arca (2 S 6:16; 1 Cr 15:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143775, 'spa', 'Abominar, hacer detestable', 'Verbo denominativo Piel que significa considerar algo como ritualmente detestable o hacerse a sí mismo abominable. En su sentido transitivo, ordena a Israel rechazar ciertas criaturas como impuras (Lv 11:11, 13) y aborrecer por completo los objetos idolátricos (Dt 7:26, emparejado con el infinitivo absoluto enfático y el sinónimo תָּעַב). En su sentido reflexivo (con נֶפֶשׁ como objeto), advierte contra contaminarse al consumir alimentos prohibidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143781, 'spa', 'Cosa detestable, abominación', 'Algo detestable a los ojos de Dios, usado principalmente de criaturas ritualmente inmundas en las leyes dietéticas levíticas: animales acuáticos sin aletas ni escamas, ciertas aves e insectos que se arrastran (Lv 11:10-13, 20, 23, 41-42). También aparece para ofrendas contaminadas (Lv 7:21) e imágenes idolátricas (Ez 8:10). Transmite repugnancia ritual visceral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143785, 'spa', 'Precipitarse, embestir', 'Movimiento físico agresivo: precipitarse, correr con ímpetu, lanzarse hacia adelante. Las langostas se precipitan por la ciudad en Joel 2:9, los saqueadores se lanzan sobre el botín en Isaías 33:4, y un gobernante malvado es como un oso que acecha en Proverbios 28:15. El Hitpalpel en Nahúm 2:4 intensifica la acción describiendo carros que se lanzan frenéticamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143787, 'spa', 'Anhelar, desear con ansia', 'Extensión metafórica del impulso físico volcado hacia el interior: anhelar, desear con inquietud, consumirse de anhelo. Se usa para el alma que anhela agua en Isaías 29:8 (junto a ''agotado'' y ''vacío'') y en Salmo 107:9 (junto a ''hambriento''). El mismo verbo capta tanto la embestida corporal como la agitación interior del deseo insatisfecho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143792, 'spa', 'Obrar con falsedad, mentir', 'Actuar con engaño, quebrantar la fe o proferir falsedad. El Qal en Génesis 21:23 se refiere a la ruptura de juramentos entre aliados. El Piel intensifica hacia la falsedad deliberada: Salmo 44:17 protesta inocencia, mientras que 1 Samuel 15:29 usa la negación para afirmar la veracidad de Dios. Levítico 19:11 lo empareja con כָּחַשׁ (negar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143798, 'spa', 'falsedad, mentira', 'El sentido dominante cubre la falsedad y la mentira como realidad sustantiva: una declaración falsa, una falta de verdad o la cualidad de ser falso. Se emplea como sujeto (''la falsedad brota''), como objeto (''hablar שֶׁקֶר,'' Jer 9:5) o en cadenas constructas (''testigos de שֶׁקֶר,'' Dt 19:18). La evidencia multilingüe es unánime: ''mentira/falsedad'' en español, ''mensonge'' en francés, ''Lüge'' en alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143805, 'spa', 'vanidad engañosa', 'Un sentido menor pero distintivo que señala la vacuidad vana y engañosa: cosas que defraudan la esperanza en lugar de proferir falsedades. En 1 S 25:21 David guardó los bienes de Nabal ''en vano''; Sal 33:17 declara al caballo de guerra שֶׁקֶר para la salvación (vacío de poder salvador); Pr 31:30 llama al encanto שֶׁקֶר (vano, ilusorio).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143806, 'spa', 'engaño, fraude', 'Engaño activo o conducta fraudulenta, donde el énfasis pasa de la declaración falsa al acto traicionero de engañar. Pr 11:18 advierte que el impío gana ''salario de שֶׁקֶר'' (ganancia fraudulenta), Pr 20:17 describe el pan obtenido con engaño, e Is 28:15 presenta un pacto con la muerte edificado sobre la mentira.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143821, 'spa', 'príncipe, noble, oficial', 'El sentido amplio por defecto que abarca personas de alto rango, autoridad o posición social en contextos políticos o reales: príncipes, nobles, oficiales de la corte, jefes tribales y dignatarios extranjeros. Con 297 apariciones es el uso abrumadoramente dominante, desde los príncipes de Moab que informan a Balac (Nm 22:8-21) hasta los oficiales de Judá condenados por los profetas (Is 1:23; Jer 34:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143823, 'spa', 'jefe de un cargo', 'Cabeza o jefe de un cargo u oficio específico, usado de modo característico en la cadena constructa שַׂר ha-X. Los ejemplos clásicos son los títulos del ciclo de José: שַׂר הַטַּבָּחִים (''jefe de la guardia,'' Gn 37:36), שַׂר הַמַּשְׁקִים (''jefe de coperos,'' Gn 40:2), שַׂר הָאֹפִים (''jefe de panaderos,'' Gn 40:2). Este patrón constructo, con 85 apariciones, crea títulos funcionales compuestos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143829, 'spa', 'capitán, comandante militar', 'Líder o oficial militar que ejerce autoridad sobre tropas u operaciones bélicas. Aparece 35 veces, especialmente en la organización mosaica de Israel (Éx 18:21-25: ''jefes de mil, de cien, de cincuenta y de diez'') y en las narrativas de conquista. El contexto militar lo distingue claramente del uso cortesano o administrativo general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143879, 'spa', 'gobernante, gobernador', 'Gobernante territorial o político que ejerce autoridad sobre una región, ciudad o pueblo. Solo 4 apariciones claras, pero contextualmente distintas: Moisés es desafiado con ''¿Quién te puso por gobernante y juez sobre nosotros?'' (Éx 2:14); los ''gobernantes'' de Samaria son autoridades políticas (2 R 10:1); el ''príncipe de Persia'' en Daniel (10:13) es un soberano cósmico territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143913, 'spa', 'Morar, habitar', 'Morar, habitar, residir — desarrollo semántico posiblemente derivado de la práctica nómada de soltar las cinchas y cargas de los animales al establecer campamento. En Daniel 2:22 la luz ''mora'' con Dios, usando el participio pasivo Peal. Este sentido se distingue claramente del significado primario de ''soltar'', habiendo evolucionado hacia una acepción locativa estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143914, 'spa', 'Soltar, desatar, resolver', 'Soltar, desatar, liberar de ataduras, con extensión figurada a resolver problemas difíciles (''desatar nudos''). En Daniel 3:25 el participio pasivo describe a los tres varones caminando ''sueltos'' en el horno, libres de sus ligaduras. Daniel 5:12 y 5:16 elogian la capacidad de Daniel para ''resolver'' (literalmente ''desatar'') enigmas interpretativos complejos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143917, 'spa', 'Comenzar, dar inicio', 'Comenzar, emprender una obra (Pael/Piel). En Esdras 5:2 Zorobabel y Jesúa ''comenzaron'' a reedificar la casa de Dios en Jerusalén. El puente semántico puede ser la idea de ''soltar'' o liberar un emprendimiento para ponerlo en marcha. Este sentido inceptivo se corresponde con el Hifil hebreo de חָלַל.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143919, 'spa', 'nombre personal', 'Nombre personal de al menos dos individuos. 2 Reyes 19:37 e Isaías 37:38 nombran a Sarezer como el hijo parricida de Senaquerib que derribó a su padre y escapó a Armenia. Zacarías 7:2 identifica a un Sarezer (diferente) enviado a indagar de los sacerdotes sobre prácticas de luto durante el período persa. Las glosas multilingües simplemente transliteran (''Sarezer''), apropiado para nombres propios sin significado transferible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143921, 'spa', 'Serebías (nombre propio)', 'El nombre propio Serebías (שֵׁרֵבְיָה), que designa a un levita prominente del período postexílico. El significado del nombre podría ser ''Yah ha enviado calor abrasador'', aunque su etimología sigue siendo incierta. Serebías aparece en la narrativa de Esdras como un hombre de capacidad excepcional, reclutado para el regreso de Babilonia (Esd 8:18) y encargado de transportar el tesoro sagrado (Esd 8:24). En Nehemías es un líder del culto público y la enseñanza de la Ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143924, 'spa', 'Cetro real', 'El cetro real, especificamente el cetro de oro del rey persa en Ester. El protocolo persa exigia la muerte de quien se acercase al rey sin ser convocado, a menos que este extendiese el cetro (Est 4:11). El rey extiende el cetro a Ester, otorgandole favor y vida (Est 5:2, 8:4). Esta vara simboliza la autoridad real y el poder de dar vida: su extension revoca la sentencia de muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143927, 'spa', 'Vestiduras tejidas sacras', 'Vestiduras especiales tejidas o trenzadas para el servicio del tabernaculo (Ex 31:10, 35:19, 39:1, 41). La tecnica exacta de tejido es incierta, posiblemente tela finamente tejida, trenzada o entrelazada. Siempre asociadas con «ministrar en el lugar santo», eran vestiduras sacerdotales de artesania distintiva. Los traductores antiguos mostraron incertidumbre (LXX «vestiduras liturgicas»), pero claramente las entendian como prendas de servicio sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143931, 'spa', 'Princesa o mujer noble', 'Princesa o mujer de la clase gobernante. El término aparece para las damas de la madre de Sísara (Jue 5:29), las esposas reales de Salomón (1 Re 11:3), las nobles persas (Est 1:18) y las reinas extranjeras en la visión restauradora de Isaías (Is 49:23). En Lam 1:1 Jerusalén es personificada como una princesa reducida a servidumbre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143932, 'spa', 'El nombre propio femenino שָׂרָה (Sara, ''princesa''), que identifica a la esposa ', 'El nombre propio femenino שָׂרָה (Sara, ''princesa''), que identifica a la esposa de Abraham y madre de Isaac. Las 38 apariciones se refieren a esta única persona a lo largo del ciclo narrativo abrahámico (Gn 17-25) y el aliento de Isaías al exilio (51:2). El cambio de nombre de Sarai a Sara (Gn 17:15) funciona como una recomisión divina paralela al propio cambio de nombre de Abraham. Los episodios clave giran en torno a la promesa de un hijo en la vejez, su risa (Gn 18:12), el nacimiento de Isaac (Gn 21:1-7) y su sepultura en Macpela (Gn 23:1-2, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143940, 'spa', 'Patriarca genealógico', 'Nombre personal de un patriarca en la línea de Sem a Abraham. Sus cinco ocurrencias son genealógicas: cuatro en la toledot de Sem (Gn 11:20-23) y una en el resumen del Cronista (1 Cr 1:26). La forma de la LXX Serouch y la transliteración uniforme como «Serug» en múltiples idiomas atestiguan la transmisión estable del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143943, 'spa', 'Sarón (topónimo)', 'Nombre propio que identifica la fértil llanura marítima de la costa mediterránea de Israel, famosa por sus pastizales y belleza natural. Aparece en contextos administrativos (1 Cr 5:16; 27:29), en la célebre «rosa de Sarón» (Cnt 2:1), y en oráculos proféticos que contrastan su florecimiento (Is 35:2) con su desolación (Is 33:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143951, 'spa', 'Silbidos con doble función', 'Sonidos de silbido o siseo con funciones duales. Jueces 5:16 pregunta por qué Rubén se sentó ''entre los silbidos de los rebaños''—llamadas de pastor a las ovejas, quizás sugiriendo paz pastoral versus urgencia de batalla. Jeremías 18:16 (con variantes Ketiv-Qere) advierte que la tierra se convertirá en objeto de ''siseo''—sonidos despreciativos hechos ante las ruinas. Las glosas multilingües (''silbidos'', ''pipings'', ''hissings'') confirman esta dualidad semántica entre señal pastoral y expresión de burla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143953, 'spa', 'Hija de Aser', 'Nombre personal de la hija de Aser, únicamente preservado en listas genealógicas. Génesis 46:17 nombra a Sera entre la casa de Jacob que migró a Egipto—una de muy pocas mujeres en el registro. Números 26:46 la menciona nuevamente en el censo del desierto de los clanes de Aser. 1 Crónicas 7:30 la repite en la genealogía de Aser. Su aparición persistente a través de las fuentes (a pesar del enfoque masculino habitual de las genealogías) marca su importancia inusual en la memoria comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143954, 'spa', 'Hacer incisiones o ser cortado', 'Hacer incisiones o cortes en la carne, o ser cortado/lacerado. Levítico 21:5 prohíbe a los sacerdotes hacer ''cortes en su carne''—autolaceración ritual asociada con ritos de luto prohibidos bajo la ley mosaica. Zacarías 12:3 (usando formas duplicadas para intensidad: ''cortando serán cortados'') advierte que las naciones que intenten mover Jerusalén ''serán gravemente laceradas''—heridas por la carga. Las glosas multilingües (''harán'', ''rasgarse'', ''se-rasgarán'') confirman este campo semántico de heridas autoinfligidas o recibidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143957, 'spa', 'Sarai (nombre propio)', 'Sarai (nombre propio). Nombre personal de la esposa de Abram antes de su cambio de nombre divinamente ordenado a Sara (''princesa'') en Génesis 17:15. Todas las ocurrencias se agrupan en Génesis 11-17: su presentación como esposa estéril de Abram en Ur (Gn 11:29-31), el viaje a Canaán (Gn 12:5), el episodio en Egipto (Gn 12:11, 17), y la narrativa de Agar (Gn 16:1-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143960, 'spa', 'Sarmientos de vides y frutales', 'Sarmientos o ramas de vides y árboles frutales. Génesis 40:10 describe una vid con tres ''ramas'' en el sueño del copero. Génesis 40:12 interpreta las tres ramas como tres días. Joel 1:7 se lamenta de que las langostas han despojado ''sus ramas''—las extremidades fructíferas de la higuera quedaron desnudas y blancas. Las glosas multilingües (''sarmientos'', ''ramas'', ''branches'', ''sarment'') confirman que esto denota los brotes fructíferos en lugar del tronco, destacando la función productiva de estas partes de la planta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143961, 'spa', 'Persona que sobrevive a una destrucción militar o a un juicio divino, frecuentem', 'Persona que sobrevive a una destrucción militar o a un juicio divino, frecuentemente emparejada con palit (''fugitivo, escapado''). Domina la fórmula de conquista ''hasta que no quedó sobreviviente'' en Deuteronomio y Josué (Nm 21:35; Dt 2:34; Jos 10:28-40). Proféticamente, la presencia de un sarid señala la misericordia de Dios: el remanente de Isaías librado del destino de Sodoma (Is 1:9), los sobrevivientes que YHWH llama en Joel (Jl 2:32), mientras que su ausencia marca el juicio total contra Esaú (Abd 18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143975, 'spa', 'Coraza, cota de malla', 'Sustantivo masculino que designa armadura corporal para el torso, una cota de malla o peto de componentes metálicos entrelazados. En 1 Samuel 17:5, la armadura de Goliat está hecha de «escamas» (qasqasim) de bronce. El mismo término describe la armadura ofrecida a David (1 S 17:38) y la atravesada por la flecha fatal en 1 Reyes 22:34.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143983, 'spa', 'Seraías (nombre propio)', 'Seraías (nombre propio). Nombre personal שְׂרָיָה, portado por múltiples figuras del AT incluyendo al secretario de David (2 Sam 8:17, con variantes Seva/Savsa/Sisa en textos paralelos), el sumo sacerdote en la destrucción de Jerusalén (2 R 25:18; Jer 52:24), un capitán militar bajo Gedalías (2 R 25:23), y ancestros en la línea sacerdotal que conduce a Esdras (Esd 7:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143988, 'spa', 'Obstinación de corazón', 'Terquedad u obstinación del corazón, siempre en la frase constructa ''dureza de (su) corazón'', que denota un rechazo voluntario y endurecido a obedecer los mandamientos del pacto de Dios. Jeremías emplea esta expresión como motivo recurrente de la desobediencia crónica de Israel (Jer 3:17; 7:24; 9:13; 11:8; 13:10; 16:12; 18:12; 23:17), mientras que Deuteronomio 29:19 y Salmo 81:12 la enmarcan como la resolución autoengañosa que conduce al juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143995, 'spa', 'Estar anormalmente extendido o estirarse', 'Estar anormalmente extendido o estirarse uno mismo. Levítico 21:18 y 22:23 usan el participio pasivo para describir deformidad física—un miembro ''extendido'' más allá de la proporción normal, ya sea en humanos o animales, descalificándolos para el servicio sagrado. Isaías 28:20 emplea el infinitivo Hitpael metafóricamente: la cama es demasiado corta ''para extenderse''—sin espacio para extenderse uno mismo, simbolizando la futilidad de confiar en refugios inadecuados. Las glosas multilingües (''deforme'', ''para-extenderse'') capturan ambos aspectos: anomalía física y extensión corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (143997, 'spa', 'quemar, prender fuego', 'El sentido activo transitivo: quemar, prender fuego o consumir algo con fuego. Es el uso abrumadoramente dominante, que abarca la destrucción de ídolos (Dt 7:5), la eliminación de restos sacrificiales (Lv 4:12) y la devastación militar (Jos 11:9). El árabe أَحْرَقَ y el suajili kuchoma lo traducen como un transitivo directo ''quemar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144000, 'spa', 'ser quemado (pasivo)', 'El sentido pasivo: ser quemado, ser consumido por el fuego. Tamar enfrenta esta sentencia en Gn 38:24, y la ley levítica prescribe que la carne sacrificial sobrante ''será quemada'' (Lv 7:17, 19). La construcción pasiva desplaza el foco del agente que quema al objeto consumido, y aparece típicamente en las conjugaciones Nifal o Pual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144012, 'spa', 'quemado (estado resultante)', 'Uso resultativo del participio pasivo Qal, que describe algo ya quemado. Sal 80:16 lamenta la vid ''quemada con fuego,'' Neh 4:2 inspecciona murallas ''quemadas'' y 1 S 30:3 encuentra Siclag ''quemada.'' Las formas participiales árabes como مُحْرَقَة distinguen este estado adjetival del proceso activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144032, 'spa', 'el que quema (agente)', 'El participio agentivo usado de modo sustantivo: ''el que quema,'' la persona que ejecuta la quema ritual. Lv 16:28 prescribe que ''el que queme'' la ofrenda por el pecado debe lavar sus vestiduras, y Nm 19:8 purifica igualmente al agente. Este papel ritual especializado se distingue como un sustantivo funcional en el texto levítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144058, 'spa', 'Serpiente ardiente venenosa', 'Serpiente venenosa cuya mordedura produce una sensación abrasadora, la «serpiente ardiente» del desierto. Números 21:6 y 21:8 describen estas criaturas letales enviadas como castigo divino, y Dt 8:15 recuerda su peligro. En Isaías 14:29 y 30:6 el término se amplía a una criatura mítica, una serpiente alada y ardiente que combina lo natural con lo sobrenatural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144061, 'spa', 'Quema, conflagración — El acto o evento de quemar, ya sea constructivo, ritual, ', 'Quema, conflagración — El acto o evento de quemar, ya sea constructivo, ritual, penal o destructivo. Génesis 11:3 lo emplea junto al verbo שָׂרַף para la cocción de ladrillos; Números 19:6 y 19:17 lo aplican a la incineración de la vaca roja en el ritual de purificación. En 2 Crónicas 16:14 y 21:19, la construcción de acusativo cognado describe la quema de especias en funerales reales, un rito ceremonial de honra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144068, 'spa', 'Marca de quemadura, cicatriz — La marca física o herida dejada por el fuego en l', 'Marca de quemadura, cicatriz — La marca física o herida dejada por el fuego en la piel: una cicatriz o señal de quemadura. Este sentido aparece en el diagnóstico levítico de afecciones cutáneas (Lv 13:24-28), donde los sacerdotes debían examinar si la marca de quemadura mostraba signos de infección. El español la traduce consistentemente como ''quemadura'' (herida por fuego) en vez de ''quema'' (acto de quemar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144072, 'spa', 'Criatura que pulula, animal rastrero — El uso participial o sustantivado que des', 'Criatura que pulula, animal rastrero — El uso participial o sustantivado que designa criaturas caracterizadas por su movimiento de enjambre o arrastre: un clasificador taxonómico para animales pequeños que se mueven en masa. Levítico 11:29-46 usa ha-shorets (''lo que pulula'') repetidamente para definir una categoría de criaturas ritualmente inmundas: comadrejas, ratones, lagartijas y sus afines. Génesis 7:21 enumera ''todo ser que pulula sobre la tierra'' entre los que perecieron en el diluvio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144073, 'spa', 'Pulular, bullir, multiplicarse — La acción verbal de criaturas vivientes que se ', 'Pulular, bullir, multiplicarse — La acción verbal de criaturas vivientes que se multiplican abundantemente, llenando un espacio al pulular o bullir en grandes cantidades. Génesis 1:20-21 lo emplea para la fecundidad primordial de la creación; Génesis 9:7 y Éxodo 1:7 lo aplican al crecimiento poblacional humano: Israel ''pululó'' en Egipto, un eco del mandato creacional. Las aguas de la visión del templo de Ezequiel (47:9) bullirán de peces por donde fluya el río.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144082, 'spa', 'Criaturas que pululan, seres rastreros — Sustantivo colectivo para animales pequ', 'Criaturas que pululan, seres rastreros — Sustantivo colectivo para animales pequeños que se mueven en enjambres o se arrastran por las superficies, abarcando criaturas acuáticas (Gn 1:20; Lv 11:10), pequeños animales terrestres como lagartijas y roedores (Lv 11:29, 41-44) e insectos alados (Lv 11:20-23; Dt 14:19). Es central en el sistema sacerdotal de pureza, donde el contacto con un שֶׁרֶץ muerto vuelve inmunda a la persona hasta el atardecer (Lv 5:2; 11:31-32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144090, 'spa', 'Silbar con escarnio', 'Silbar con escarnio y horror ante lugares devastados — reacción sibilante que expresa desprecio y estupor ante la ruina. Se dirige a las ruinas de Jerusalén (1 R 9:8; Jer 19:8; 49:17; 50:13; Lm 2:15-16), a Tiro caída (Ez 27:36) y a tierras desoladas (Mi 6:16). Acompaña al meneo de cabeza como señal de asombro despreciativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144101, 'spa', 'Silbido de escarnio', 'Sustantivo femenino que denota un silbido burlón o chiflido despectivo, siempre emparejado con shammah («desolación») en contextos proféticos de juicio. La fórmula shammah u-shereqah («desolación y silbido») expresa la ruina total bajo la ira divina. Jeremías la despliega contra Jerusalén (Jer 19:8), las naciones (Jer 25:9, 18), Babilonia (Jer 51:37) y el exilio (Jer 29:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144107, 'spa', 'Gobernar, ejercer autoridad', 'Ejercer autoridad principesca, gobernar o enseñorearse, según la conjugación y el contexto. En Isaías 32:1 los príncipes gobiernan con justicia junto a un rey recto. En Números 16:13, el Hitpael intensifica la expresión como acusación de tiranía: ''te sigues enseñoreando sobre nosotros''. Proverbios 8:16 afirma que los gobernantes rigen por medio de la Sabiduría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144113, 'spa', 'Enemigo acechador', 'Vigía hostil o enemigo al acecho, que observa con intención maliciosa. Las cinco ocurrencias son sálmicas, siempre con sufijo de primera persona: el salmista pide guía a causa de «mis acechadores» (Sal 5:8; 27:11), apela a la vindicación divina contra ellos (Sal 54:5; 59:10) y lamenta su persecución incesante (Sal 56:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144116, 'spa', 'Echar raíces, arraigarse', 'Echar raíces, establecerse firmemente — dicho del futuro florecimiento de Israel (Is 27:6), de una vid plantada por Dios (Sal 80:9), o incluso de la engañosa prosperidad de los impíos (Jer 12:2; Is 40:24). Las traducciones «echando raíces» y «arraigado» destacan el proceso gradual y orgánico de asentarse profundamente. Abarca las formas Hiphil, Poal y Poel en cinco apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144118, 'spa', 'Desarraigar, arrancar', 'Desarraigar, arrancar de raíz — destrucción activa en la forma Piel. En Salmo 52:5, Dios desarraiga al engañador de la tierra de los vivientes; en Job 31:12, el fuego metafóricamente «arranca» toda la cosecha. La traducción española «desarraigará» refleja fielmente la violenta inversión del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144123, 'spa', 'Ser desarraigado', 'Ser desarraigado — forma pasiva Pual, que aparece una sola vez en Job 31:8, donde Job invoca una automaldición: «sea desarraigado lo que planté». La traducción «serán desarraigados» confirma el valor pasivo. Esta única aparición completa el par activo-pasivo con el sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144124, 'spa', 'La raíz botánica literal de un árbol o planta — la parte subterránea que ancla, ', 'La raíz botánica literal de un árbol o planta — la parte subterránea que ancla, nutre o es destruida en el juicio. Se usa para raíces que se extienden junto al agua (Job 8:17; 29:19), que se secan en el castigo divino (Os 9:16; Am 2:9; Mal 4:1), y que se afianzan hacia abajo para dar fruto hacia arriba (2 R 19:30 = Is 37:31). La imagen concreta de arraigo y destrucción proporciona la base para las extensiones metafóricas del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144125, 'spa', 'Uso figurado de raíz para denotar linaje ancestral, estirpe, fuente o causa suby', 'Uso figurado de raíz para denotar linaje ancestral, estirpe, fuente o causa subyacente. La ''raíz de Isaí'' (Is 11:1, 10) se convierte en un título mesiánico fundamental, mientras que ''la raíz del asunto'' (Job 19:28) significa la causa esencial. Isaías 14:29 advierte que de la raíz de la serpiente saldrá una víbora. Proverbios 12:3, 12 contrasta la raíz del justo que permanece firme con la del impío que perece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144144, 'spa', 'Raíces en simbolismo', 'Raíces de árbol en el simbolismo del sueño de Nabucodonosor. Daniel 4:12 (arameo 4:15) ordena dejar ''sus raíces en la tierra'' al cortar el gran árbol. Daniel 4:20 y 4:23 (arameo 4:23, 26) repiten la instrucción sobre preservar ''las raíces'' como señal de que ''tu reino será tuyo'' después de reconocer el gobierno celestial. El sistema de raíces preservado asegura restauración eventual: el árbol puede crecer nuevamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144147, 'spa', 'Cadenas, cadenillas', 'Cadenas de trabajo metálico trenzado, empleadas con fines ornamentales y sagrados. En las vestiduras sacerdotales, las sharshrot de oro sujetan el pectoral al efod (Éx 28:14, 22; 39:15), descritas como «cadenas de labor trenzada». En la arquitectura del Templo, adornan los capiteles de las columnas de bronce (1 R 7:17) y el interior (2 Cr 3:5, 15-16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144151, 'spa', 'Ministrar, servir', 'Ministrar, servir. La acción verbal de ministrar o servir en una posición de honor, ya sea en funciones cultuales/sacerdotales o como asistente personal de un superior. Cubre las formas finitas e infinitivas del tronco Piel. Los levitas sirven (שָׁרַת) ante el tabernáculo (Nm 3:6), y los sacerdotes ministran en el santuario (Éx 28:35). El español ''ministrar'' y el alemán ''dienen'' captan el registro elevado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144152, 'spa', 'Ministro, servidor, asistente', 'Ministro, servidor, asistente. Participio sustantivado que funciona como sustantivo: ''ministro'', ''asistente'', ''servidor'', alguien que ocupa un rol reconocido de servicio honorable. Josué es llamado מְשָׁרֵת מֹשֶׁה, ''ministro de Moisés'' (Éx 24:13; Jos 1:1), y Samuel sirve como asistente ante el Señor (1 S 2:11). El francés ''serviteur'' y el alemán ''Diener'' lo traducen como un título de oficio digno, no de trabajo servil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144196, 'spa', 'Piedra mármol arquitectónico', 'Piedra de mármol en contextos arquitectónicos y poéticos. Ester 1:6 (apareciendo tres veces en el versículo) describe el patio del palacio de Asuero con pilares de mármol y pavimento de mármol (junto con pórfido y otras piedras preciosas), típico de la grandeza imperial persa. Cantar de los Cantares 5:15 usa mármol metafóricamente: las piernas del amado son ''pilares de mármol'', fuertes, blancas, hermosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144197, 'spa', 'Lino fino egipcio o biso, un textil blanco de primera calidad asociado con la re', 'Lino fino egipcio o biso, un textil blanco de primera calidad asociado con la realeza, el sacerdocio y el espacio sagrado. En los textos del tabernáculo (Éx 25-28, 35-39), שֵׁשׁ es la tela base de casi todo elemento tejido: cortinas (26:1, 31, 36), los colgantes del atrio (27:9, 18) y las vestiduras sacerdotales (28:5, 6, 8, 15, 39; 39:2-29). Fuera del tabernáculo, marca favor real cuando Faraón viste a José con vestiduras de lino fino (Gn 41:42), y Ezequiel lo usa metafóricamente para el esplendor del pacto de Dios con Jerusalén (Ez 16:10, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144206, 'spa', 'seis (número cardinal)', 'El número cardinal seis, en formas masculina (שֵׁשׁ) y femenina (שִׁשָּׁה), tanto en estado absoluto como constructo. Funciona de modo independiente (''seis días,'' Éx 20:9; ''seis codos,'' 1 S 17:4) y como componente base en numerales compuestos (dieciséis, sesenta, seiscientos). Su contexto teológico más prominente son los seis días de creación y labor que preceden al descanso sabático (Gn 1; Éx 23:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144228, 'spa', 'Exultación, regocijo o alegría festiva, especialmente como respuesta a los actos', 'Exultación, regocijo o alegría festiva, especialmente como respuesta a los actos salvíficos de Dios o a su favor pactal. Frecuentemente emparejada con simkhah en textos proféticos y litúrgicos: Jeremías usa el par para describir tanto el silenciamiento del gozo bajo el juicio (Jer 7:34; 16:9) como su prometida restauración (Jer 33:11). Los Salmos la emplean para la renovación espiritual (''devuélveme el gozo de tu salvación'', Sal 51:12), e Isaías la transforma en ''óleo de gozo'' que reemplaza el luto (Is 61:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144237, 'spa', 'Gigante anaceo', 'Nombre personal de un gigante anaceo. Números 13:22 identifica a Sesai como uno de los descendientes de Anac que habitaban en Hebrón cuando los doce espías exploraron Canaán. Josué 15:14 reporta que Caleb expulsó a Sesai y sus dos hermanos de Hebrón como parte de su herencia. Jueces 1:10 confirma que Judá derrotó a los tres hijos de Anac. El nombre funciona tanto individualmente (la persona Sesai) como tribalmente (su clan).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144238, 'spa', 'El numeral ordinal ''sexto'', que marca posición secuencial en listas de días, mes', 'El numeral ordinal ''sexto'', que marca posición secuencial en listas de días, meses, años, personas o grupos. Se usa para el sexto día de la creación, cuando Dios completó su obra y la declaró muy buena (Gn 1:31), el sexto hijo Neftalí (Gn 30:19) y el sexto mes o año en diversas referencias cronológicas (Ez 8:1). Las glosas multilingües son uniformemente ordinales: español sexto, francés sixième, alemán sechste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144239, 'spa', 'Una cantidad fraccionaria que significa un sexto de una unidad de medida, usada ', 'Una cantidad fraccionaria que significa un sexto de una unidad de medida, usada exclusivamente en la legislación sacerdotal de Ezequiel para ofrendas y provisiones. La sexta parte de un hin de vino (Ez 4:11) y un sexto de efa de grano (Ez 45:13; 46:14) emplean esta construcción partitiva. El español sexta parte de y el inglés ''sixth of'' señalan el cambio de posición ordinal a proporción medida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144245, 'spa', 'Sesenta', 'Sesenta. El número cardinal sesenta, usado en edades genealógicas (Gn 5:15, 21), dimensiones del templo (1 R 6:2; Ez 40:14), conteos de tropas y períodos legales. Las traducciones son directamente numéricas: español ''sesenta'', francés ''soixante'', alemán ''sechzig''. La consistencia en las 59 apariciones confirma un único sentido numérico inequívoco sin extensión figurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144250, 'spa', 'Nombre propio judío', 'Nombre personal de Sesán, un judío del clan jerahmeelita. Sus cinco attestaciones aparecen en 1 Cr 2:31-35, donde la genealogía señala que no tuvo hijos varones y dio a su hija en matrimonio a su siervo egipcio Jarhá. Las variantes de la LXX Sosan y Sisan reflejan diferencias menores de transliteración, pero un referente único y consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144254, 'spa', 'Set (nombre propio)', 'Sustantivo propio masculino Set (שֵׁת), que designa al hijo nacido de Adan y Eva como reemplazo divinamente designado del asesinado Abel (Gen 4:25-26). El nombre se conecta popularmente con el verbo שִׁית (''poner, colocar, designar''), reflejando la declaracion de Eva de que Dios le ''puso'' otra descendencia. La genealogia de Genesis 5:3-8 traza la linea de Set a traves de Enos hasta Noe, estableciendolo como progenitor de toda la humanidad posdiluviana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144257, 'spa', 'beber, consumir líquido', 'El sentido verbal nuclear: beber, consumir un líquido. Con 209 apariciones, cubre todas las formas finitas (perfecto, imperfecto, imperativo, yusivo, consecutivo) e infinitivos que denotan el acto de beber agua, vino, leche o cualquier bebida. Aparece en escenas de hospitalidad (Gn 24:14), comidas de pacto (Gn 26:30) y actos proféticos simbólicos (Ez 4:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144270, 'spa', 'bebedor, el que bebe', 'Participio sustantivado: bebedor, el que bebe. Siete apariciones donde el participio Qal funciona como sustantivo agentivo que caracteriza a una persona por su hábito de beber. Jl 1:5 convoca a ''todos los bebedores de vino'' al llanto; Sal 69:12 lamenta ser la canción de ''los bebedores de licor''; Ez 31:14, 16 habla de árboles entre ''bebedores de agua'' (árboles bien regados personificados).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (144334, 'spa', 'ser bebido (pasivo)', 'Uso pasivo o estativo: ser bebido, ser consumido como líquido. Una sola aparición en Lv 11:34, donde emerge el sentido pasivo (Nifal): ''toda bebida que pueda ser bebida'' en el contexto de las leyes de pureza alimentaria. La formulación pasiva desplaza el foco del agente que bebe al líquido que es consumido.');